import Foundation

enum NeovimThemeReloader {
    // A native runtime plugin works with plain Neovim, AstroNvim and LazyVim.
    // Poll the path rather than an inode: theme writes replace files atomically.
    static let script = #"""
    -- Generated by MWall. Set vim.g.mwall_auto_reload = false to opt out.
    if vim.g.loaded_mwall_reload then
      return
    end

    local uv = vim.uv or vim.loop
    local timer = assert(uv.new_timer())
    vim.g.loaded_mwall_reload = true
    local source = debug.getinfo(1, "S").source:sub(2)
    local colors = vim.fn.fnamemodify(source, ":p:h:h") .. "/colors/"
    local schemes = { mwall = true, ["mwall-dark"] = true, ["mwall-light"] = true }
    local last_scheme, last_content
    local closed = false

    local function read_current()
      local scheme = vim.g.colors_name
      if not schemes[scheme] then
        return
      end
      local path = colors .. scheme .. ".lua"
      local file = io.open(path, "rb")
      if not file then
        return
      end
      local content = file:read("*a")
      file:close()
      return scheme, content, path
    end

    local function check()
      if closed or vim.g.mwall_auto_reload == false then
        return
      end
      local scheme, content, path = read_current()
      if not content or (scheme == last_scheme and content == last_content) then
        return
      end
      -- Remember failed content too, so a bad file produces only one notification.
      -- A later valid replacement will still be picked up automatically.
      last_scheme, last_content = scheme, content
      local chunk, err = loadstring(content, "@" .. path)
      if chunk then
        if vim.loader and vim.loader.reset then
          vim.loader.reset(path)
        end
        local ok
        ok, err = pcall(vim.cmd.colorscheme, scheme)
        if ok then
          -- :colorscheme emits ColorScheme, preserving user/plugin highlight overrides.
          vim.cmd("redraw!")
          return
        end
      end
      vim.notify("MWall theme reload failed: " .. tostring(err), vim.log.levels.WARN)
    end

    local group = vim.api.nvim_create_augroup("MWallThemeReload", { clear = true })
    vim.api.nvim_create_autocmd("ColorScheme", {
      group = group,
      callback = function()
        last_scheme, last_content = read_current()
      end,
    })
    vim.api.nvim_create_autocmd("FocusGained", {
      group = group,
      callback = check,
    })
    vim.api.nvim_create_autocmd("VimLeavePre", {
      group = group,
      once = true,
      callback = function()
        closed = true
        timer:stop()
        timer:close()
      end,
    })
    -- Check on the main loop; no focus change or editor command is required.
    timer:start(1000, 1000, vim.schedule_wrap(check))
    """# + "\n"
}
